mapper.update:
UPDATE teaching_class_schedule
classroom_id = #{classroomId}, weekday = #{weekday}, start_section = #{startSection}, end_section = #{endSection}, start_week = #{startWeek}, end_week = #{endWeek},
WHERE id = #{id}

mapper.sql:
FROM teaching_class_schedule tcs
JOIN teaching_class conflict_tc ON conflict_tc.id = tcs.teaching_class_id
JOIN teaching_class current_tc ON current_tc.id = #{teachingClassId}
WHERE conflict_tc.semester_id = current_tc.semester_id
AND tcs.id <> IFNULL(#{excludeScheduleId}, 0)
AND tcs.weekday = #{weekday}
AND tcs.start_week <= #{endWeek}
AND tcs.end_week >= #{startWeek}
AND tcs.start_section <= #{endSection}
AND tcs.end_section >= #{startSection}
